/**
 * Текст не короче `minChars`: абзацы по 3 предложения, последний добирается
 * по одному — поэтому объём попадает в «живой» диапазон с точностью до
 * одного предложения, а не удваивается.
 */
export function sectionOfMinChars(minChars: number, minParagraphs = 2): string {
  const paragraphs: string[] = [];
  let cursor = 0;
  let total = 0;

  const next = (): string => {
    const sentence = LONG_POOL[cursor % LONG_POOL.length] ?? '';
    cursor += 1;
    return sentence;
  };
  const push = (sentences: string[]): void => {
    const paragraph = sentences.join(' ');
    paragraphs.push(paragraph);
    total += paragraph.length + 2;
  };

  while (total < minChars || paragraphs.length < minParagraphs) {
    const remaining = minChars - total;
    // Пока до цели далеко — целый абзац; у самого края добираем по одному
    // предложению, но не меньше двух (правило формы).
    if (remaining > 260 || paragraphs.length < minParagraphs - 1) {
      push([next(), next(), next()]);
      continue;
    }
    const tail = [next(), next()];
    while (total + tail.join(' ').length < minChars) {
      tail.push(next());
    }
    push(tail);
  }

  return paragraphs.join('\n\n');
}

/**
 * `steps` заданного объёма и заданного числа пунктов (итерация 28).
 *
 * Живой прогон `46d8b893`: первый ответ — 651 знак, второй — 799, оба при
 * границах 400–550. Оба обязаны превратиться в три пункта с подписью и
 * **не** потерять третий пункт.
 */
export function stepsOfVolume(total: number, items = 3): string {
  // «— » (2 знака) + пункт + перевод строки (1 знак, кроме последнего).
  const bodyBudget = total - items * 2 - (items - 1);

  const build = (budget: number): string[] => {
    const lines: string[] = [];
    let cursor = 0;
    let used = 0;

    for (let index = 0; index < items; index += 1) {
      // Последний пункт забирает остаток: сумма попадает в цель, а не «примерно».
      const limit =
        index === items - 1
          ? Math.max(40, budget - used)
          : Math.max(40, Math.floor(budget / items));
      const sentences: string[] = [];
      let length = 0;
      while (length < limit + 40 && sentences.length < 10) {
        const sentence = LONG_POOL[cursor % LONG_POOL.length] ?? '';
        cursor += 1;
        sentences.push(sentence);
        length += sentence.length + 1;
      }
      const text = trimStepsItem(sentences.join(' '), limit);
      used += text.length;
      lines.push(`— ${text}`);
    }

    return lines;
  };

  let lines = build(bodyBudget);
  const shortfall = total - (lines.join('\n').length);
  if (shortfall !== 0) {
    lines = build(bodyBudget + shortfall);
  }

  return lines.join('\n');
}

/**
 * Слишком длинный `steps`: три пункта, в каждом по три предложения.
 *
 * Обрезка обязана сохранить все три пункта: список из двух пунктов — уже
 * другой продукт, и валидатор справедливо его не примет.
 */
export function longSteps(minChars = 900): string {
  const items: string[][] = [0, 1, 2].map((offset) =>
    [0, 1, 2].map((index) => LONG_POOL[(offset * 3 + index) % LONG_POOL.length] ?? ''),
  );

  const textOf = (): string => items.map((sentences) => `— ${sentences.join(' ')}`).join('\n');

  let cursor = 9;
  while (textOf().length < minChars && cursor < 200) {
    const item = items[cursor % 3];
    item?.push(LONG_POOL[cursor % LONG_POOL.length] ?? '');
    cursor += 1;
  }

  return textOf();
}
